export type LogoName = keyof typeof LOGOS

/** Width over height, from the logo's own viewBox. */
export function logoAspect(name: string) {
  const logo = LOGOS[name]
  if (!logo) return 1
  const [, , w, h] = logo.viewBox.split(/\s+/).map(Number)
  return w && h ? w / h : 1
}

export function ProjectLogo({
  name,
  size = 68,
  className,
}: {
  name: LogoName | string
  /** The longest edge. A wordmark keeps its proportions rather than squashing. */
  size?: number
  className?: string
}) {
  const logo = LOGOS[name]
  if (!logo) return null
  const aspect = logoAspect(name)
  const [w, h] = aspect >= 1 ? [size, size / aspect] : [size * aspect, size]
  return (
    <svg
      width={w}
      height={h}
      viewBox={logo.viewBox}
      fill="currentColor"
      className={className}
      aria-hidden
      focusable="false"
      dangerouslySetInnerHTML={{ __html: logo.inner }}
    />
  )
}

export const LOGO_NAMES = Object.keys(LOGOS)
